//! The host run against real plugin processes: the well-behaved example
//! through every capability, and each misbehaving plugin through what the
//! host owes the game whatever a plugin does. No network: every song is
//! generated by the plugins. Timeouts are shortened so a hang is found in
//! about a second; the bounds are the protocol's own.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use ddi_library::path::RelPath;
use ddi_library::scan::Reader as _;
use ddi_source_host::host::{Event, Failure, HostFailure, Request, Stop};
use ddi_source_host::installed::{Found, discover, platform};
use ddi_source_host::store::{ItemKey, Store, StoreLimits};
use ddi_source_host::{Host, HostConfig, Timeouts};
use ddi_source_protocol::{Capability, FailCode, FilterValue, Input, InputKind, OpId};

const EXAMPLE: &str = env!("CARGO_BIN_EXE_ddi-example-source");
const BAD: &str = env!("CARGO_BIN_EXE_ddi-bad-source");

fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("ddi-plugin-host-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir.canonicalize().unwrap()
}

/// Installs `binary` as plugin `id` in `plugins` (its executable named
/// `id`, which is how the misbehaving plugin knows what to do).
fn install(plugins: &Path, id: &str, binary: &str, capabilities: &str, inputs: &str) {
    let dir = plugins.join(id);
    let bin = dir.join("bin").join(platform());
    std::fs::create_dir_all(&bin).unwrap();
    std::fs::copy(binary, bin.join(format!("{id}{}", std::env::consts::EXE_SUFFIX))).unwrap();
    std::fs::write(
        dir.join("plugin.toml"),
        format!(
            "id = \"{id}\"\nname = {{ en = \"{id}\" }}\npublisher = \"Tests\"\nversion = \"1.0.0\"\nprotocol = [1]\nexecutable = \"{id}\"\ncapabilities = {capabilities}\ninputs = {inputs}\n"
        ),
    )
    .unwrap();
}

fn timeouts() -> Timeouts {
    Timeouts {
        hello: Duration::from_secs(2),
        silence: Duration::from_secs(1),
        search: Duration::from_secs(2),
        cancel: Duration::from_secs(1),
        stop: Duration::from_secs(1),
        idle: Duration::from_secs(30),
    }
}

struct Rig {
    root: PathBuf,
    host: Host,
}

impl Drop for Rig {
    fn drop(&mut self) {
        self.host.shutdown();
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

const BAD_CAPABILITIES: &str = r#"["search", "metadata", "fetch"]"#;

/// A host over the plugins `bad` (misbehaving ones, by name) and the
/// example, those in `on` switched on.
fn rig(name: &str, bad: &[&str], on: &[&str], limits: StoreLimits, timeouts: Timeouts) -> Rig {
    let root = scratch(name);
    let plugins = root.join("data/plugins");
    install(
        &plugins,
        "example",
        EXAMPLE,
        r#"["input", "search", "filters", "browse", "metadata", "fetch"]"#,
        r#"["url"]"#,
    );
    for id in bad {
        install(&plugins, id, BAD, BAD_CAPABILITIES, "[]");
    }
    let installed = discover(&plugins)
        .into_iter()
        .map(|f| match f {
            Found::Plugin(p) => p,
            Found::Refused { dir, problem } => panic!("{dir:?}: {problem:?}"),
        })
        .collect();
    let mut config = HostConfig::new(root.join("cache/plugins"), root.join("data/plugin-data"));
    config.app_version = "test".into();
    config.timeouts = timeouts;
    let store = Store::open(root.join("cache/sources"), limits).shared();
    let on: BTreeSet<String> = on.iter().map(|s| s.to_string()).collect();
    Rig {
        host: Host::new(config, installed, &on, store, None),
        root,
    }
}

fn plain(name: &str, bad: &[&str]) -> Rig {
    let mut on = vec!["example"];
    on.extend_from_slice(bad);
    rig(name, bad, &on, StoreLimits::default(), timeouts())
}

/// Events until `op` ends (at most `within`).
fn until_end(host: &mut Host, op: OpId, within: Duration) -> Vec<Event> {
    let deadline = Instant::now() + within;
    let mut out = Vec::new();
    while Instant::now() < deadline {
        let Some(e) = host.wait_event(Duration::from_millis(50)) else {
            continue;
        };
        let ends = e.ends() == Some(op);
        out.push(e);
        if ends {
            return out;
        }
    }
    panic!("operation {op} did not end within {within:?}: {out:#?}");
}

/// Events until the plugin's process ends.
fn until_stopped(host: &mut Host, within: Duration) -> (Vec<Event>, Stop, bool, Option<String>) {
    let deadline = Instant::now() + within;
    let mut out = Vec::new();
    while Instant::now() < deadline {
        if let Some(e) = host.wait_event(Duration::from_millis(50)) {
            if let Event::Stopped {
                why,
                off,
                diagnostics,
                ..
            } = &e
            {
                let r = (why.clone(), *off, diagnostics.clone());
                return (out, r.0, r.1, r.2);
            }
            out.push(e);
        }
    }
    panic!("the plugin did not stop within {within:?}: {out:#?}");
}

fn search(query: &str, page_size: u32) -> Request {
    Request::Search {
        scope: None,
        query: query.into(),
        filters: Default::default(),
        cursor: None,
        page_size,
    }
}

fn fetch(item: &str, size: Option<u64>) -> Request {
    Request::Fetch {
        item: item.into(),
        revision: None,
        size,
        rooms: None,
    }
}

fn failure(events: &[Event]) -> &Failure {
    match events.last() {
        Some(Event::Failed { failure, .. }) => failure,
        other => panic!("not a failure: {other:#?}"),
    }
}

const LONG: Duration = Duration::from_secs(20);

#[test]
fn the_example_searches_pages_filters_browses_opens_and_describes() {
    let mut r = plain("example", &[]);
    let h = &mut r.host;
    assert!(h.start("example"));
    match h.wait_event(LONG) {
        Some(Event::Ready { plugin, accepted }) => {
            assert_eq!(plugin, "example");
            assert!(accepted.capabilities.contains(&Capability::Browse));
            assert_eq!(accepted.filters.len(), 3);
            assert_eq!(accepted.filters[0].label.get("ja"), "レベル");
        }
        other => panic!("{other:?}"),
    }
    let op = h.request("example", search("", 10));
    let events = until_end(h, op, LONG);
    let items: usize = events
        .iter()
        .map(|e| match e {
            Event::Results { items, .. } => items.len(),
            _ => 0,
        })
        .sum();
    assert_eq!(items, 10);
    let Some(Event::Done { cursor, total, .. }) = events.last() else {
        panic!("{events:?}")
    };
    assert_eq!((cursor.as_deref(), *total), (Some("10"), Some(24)));
    // The last page.
    let op = h.request(
        "example",
        Request::Search {
            scope: None,
            query: "song".into(),
            filters: Default::default(),
            cursor: Some("20".into()),
            page_size: 10,
        },
    );
    let events = until_end(h, op, LONG);
    assert!(matches!(events.last(), Some(Event::Done { cursor: None, .. })));
    // Filters: a level range and a style.
    let filters = [
        (
            "level".to_string(),
            FilterValue::Range {
                min: None,
                max: Some(3.0),
            },
        ),
        (
            "style".to_string(),
            FilterValue::Choice {
                values: vec!["double".into()],
            },
        ),
    ]
    .into();
    let op = h.request(
        "example",
        Request::Search {
            scope: None,
            query: String::new(),
            filters,
            cursor: None,
            page_size: 50,
        },
    );
    let events = until_end(h, op, LONG);
    let found: Vec<String> = events
        .iter()
        .flat_map(|e| match e {
            Event::Results { items, .. } => items.iter().map(|i| i.id.clone()).collect(),
            _ => vec![],
        })
        .collect();
    // Meters 1 to 3 (`n % 15 + 1`) are songs 1, 2 and 15 to 17; the
    // even have a double.
    assert_eq!(found, ["song-2", "song-16"]);
    // A value the filter does not take never reaches the plugin.
    let bad = [(
        "level".to_string(),
        FilterValue::Range {
            min: Some(99.0),
            max: None,
        },
    )]
    .into();
    let op = h.request(
        "example",
        Request::Search {
            scope: None,
            query: String::new(),
            filters: bad,
            cursor: None,
            page_size: 5,
        },
    );
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::Unsupported)
    );
    // Browse: the packs, then a pack's songs.
    let op = h.request(
        "example",
        Request::Browse {
            scope: None,
            node: None,
            cursor: None,
            page_size: 50,
        },
    );
    let events = until_end(h, op, LONG);
    assert!(matches!(&events[0], Event::Nodes { nodes, .. } if nodes.len() == 2));
    let op = h.request(
        "example",
        Request::Browse {
            scope: None,
            node: Some("pack-b".into()),
            cursor: None,
            page_size: 50,
        },
    );
    let events = until_end(h, op, LONG);
    assert!(matches!(&events[0], Event::Results { items, .. } if items.len() == 12));
    // Open a link, describe an item, ask for one that is not there.
    let op = h.request(
        "example",
        Request::Open(Input {
            kind: InputKind::Url,
            value: "https://songs.invalid/pack-a".into(),
        }),
    );
    assert!(matches!(
        until_end(h, op, LONG).last(),
        Some(Event::Opened { scope, .. }) if scope == "pack-a"
    ));
    let op = h.request(
        "example",
        Request::Describe {
            item: "song-5".into(),
        },
    );
    assert!(matches!(
        until_end(h, op, LONG).last(),
        Some(Event::Item { item, .. }) if item.title == "Generated Song 5" && item.charts.len() == 1
    ));
    let op = h.request(
        "example",
        Request::Describe {
            item: "song-99".into(),
        },
    );
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Plugin {
            code: FailCode::NotFound,
            detail: None
        }
    );
    // An input it does not take.
    let op = h.request(
        "example",
        Request::Open(Input {
            kind: InputKind::Folder,
            value: "/tmp".into(),
        }),
    );
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::Unsupported)
    );
    assert_eq!(h.strikes("example"), 0);
}

#[test]
fn fetched_songs_land_in_memory_in_the_cache_folder_or_in_place() {
    let limits = StoreLimits {
        item_memory: 1 << 20,
        ..StoreLimits::default()
    };
    let mut r = rig("fetch", &[], &["example"], limits, timeouts());
    let store = r.host.store().clone();
    let h = &mut r.host;
    // Streamed files, into memory.
    let op = h.request("example", fetch("song-3", None));
    let events = until_end(h, op, LONG);
    let Some(Event::Fetched { key, songs, .. }) = events.last() else {
        panic!("{events:#?}")
    };
    let key = *key;
    assert_eq!(key, ItemKey::of("example", "song-3", None));
    assert_eq!(songs.len(), 1);
    let song = &songs[0];
    assert_eq!(song.id, key.song_id(0));
    assert_eq!(song.entry.title, "Generated Song 3");
    assert!(song.song_key.as_deref().is_some_and(|k| k.starts_with("s1:")));
    {
        let mut s = store.lock().unwrap();
        assert!(!s.on_disk(key));
        assert!(s.usage().memory > 4000);
        let (found, files) = s.song(&song.id).unwrap();
        let chart = files
            .read(&found.dir.join(found.entry.chart.as_str()))
            .unwrap();
        assert!(String::from_utf8(chart).unwrap().contains("#TITLE:Generated Song 3;"));
    }
    // Again: from the store, not the plugin.
    let op = h.request("example", fetch("song-3", None));
    assert!(matches!(
        until_end(h, op, LONG).as_slice(),
        [Event::Fetched { key: k, .. }] if *k == key
    ));
    // A zip of three songs.
    let op = h.request("example", fetch("pack-a.zip", None));
    let events = until_end(h, op, LONG);
    let Some(Event::Fetched { songs, .. }) = events.last() else {
        panic!("{events:#?}")
    };
    assert_eq!(songs.len(), 3);
    assert!(songs.iter().all(|s| s.pack == "Pack A"));
    // Past the item's memory budget: into the folder the host gives.
    let op = h.request("example", fetch("big-song", Some(200 << 20)));
    let events = until_end(h, op, LONG);
    let Some(Event::Fetched { key: big, songs, .. }) = events.last() else {
        panic!("{events:#?}")
    };
    assert_eq!(songs[0].entry.title, "Generated Song 7");
    assert!(store.lock().unwrap().on_disk(*big));
    // Where it already is.
    let op = h.request("example", fetch("local", None));
    let events = until_end(h, op, LONG);
    let Some(Event::Fetched { key: local, songs, .. }) = events.last() else {
        panic!("{events:#?}")
    };
    assert_eq!(songs.len(), 1);
    let files = store.lock().unwrap().files(*local).unwrap();
    assert!(matches!(
        files.get(RelPath::new("Local Song/song.ssc")),
        Some(ddi_source_host::store::Stored::Disk(p)) if p.starts_with(r.root.join("data/plugin-data/example"))
    ));
    // A slow fetch cancelled: failed at once, the plugin unharmed.
    let h = &mut r.host;
    let op = h.request("example", fetch("slow-song", None));
    std::thread::sleep(Duration::from_millis(200));
    h.cancel(op);
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::Cancelled)
    );
    let op = h.request("example", search("song 1", 5));
    assert!(matches!(until_end(h, op, LONG).last(), Some(Event::Done { .. })));
    assert_eq!(h.strikes("example"), 0);
}

#[test]
fn plugins_are_off_until_switched_on_and_unknown_ones_are_not_installed() {
    let mut r = rig("off", &[], &[], StoreLimits::default(), timeouts());
    let h = &mut r.host;
    assert!(!h.start("example"));
    let op = h.request("example", search("", 5));
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::SwitchedOff)
    );
    let op = h.request("nobody", search("", 5));
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::NotInstalled)
    );
    // Nothing was started.
    assert!(h.wait_event(Duration::from_millis(200)).is_none());
}

/// One misbehaving plugin asked `request`: how its operation failed, and
/// how its process ended.
fn misbehave(name: &str, request: Request) -> (Failure, Stop, Option<String>, Duration) {
    let mut r = plain(name, &[name]);
    let h = &mut r.host;
    let started = Instant::now();
    let op = h.request(name, request);
    let events = until_end(h, op, LONG);
    let fail = failure(&events).clone();
    let (_, why, _, diagnostics) = until_stopped(h, LONG);
    assert_eq!(h.strikes(name), u32::from(why.strikes()), "{why:?}");
    (fail, why, diagnostics, started.elapsed())
}

#[test]
fn a_plugin_that_never_says_hello_is_stopped() {
    let (f, why, _, took) = misbehave("hang-hello", search("", 5));
    assert_eq!(f, Failure::Host(HostFailure::TimedOut));
    assert_eq!(why, Stop::TimedOut);
    assert!(took < Duration::from_secs(5), "{took:?}");
}

#[test]
fn a_plugin_that_goes_silent_is_stopped() {
    let (f, why, _, took) = misbehave("hang-search", search("", 5));
    assert_eq!(f, Failure::Host(HostFailure::TimedOut));
    assert_eq!(why, Stop::TimedOut);
    assert!(took < Duration::from_secs(5), "{took:?}");
}

#[test]
fn a_plugin_that_ignores_a_cancel_is_stopped() {
    let mut r = plain("ignore-cancel", &["ignore-cancel"]);
    let h = &mut r.host;
    let op = h.request("ignore-cancel", search("", 5));
    std::thread::sleep(Duration::from_millis(300));
    h.cancel(op);
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::Cancelled)
    );
    let (_, why, _, _) = until_stopped(h, LONG);
    assert_eq!(why, Stop::TimedOut);
}

#[test]
fn a_crash_fails_its_operation_with_the_last_of_its_diagnostics_and_three_turn_it_off() {
    let mut r = plain("crash", &["crash"]);
    let h = &mut r.host;
    for n in 1..=3 {
        let op = h.request("crash", search("", 5));
        let events = until_end(h, op, LONG);
        let Some(Event::Failed {
            failure,
            diagnostics,
            ..
        }) = events.last()
        else {
            panic!("{events:#?}")
        };
        assert_eq!(failure, &Failure::Host(HostFailure::Crashed));
        let d = diagnostics.as_deref().unwrap();
        assert!(d.len() <= 32 << 10 && d.ends_with("boom: crashed on purpose"), "{}", d.len());
        let (_, why, off, _) = until_stopped(h, LONG);
        assert!(matches!(why, Stop::Crashed(Some(_))), "{why:?}");
        assert_eq!(off, n == 3);
    }
    assert!(h.is_off_for_the_run("crash"));
    let op = h.request("crash", search("", 5));
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::OffForTheRun)
    );
    // Another plugin is unaffected.
    let op = h.request("example", search("", 5));
    assert!(matches!(until_end(h, op, LONG).last(), Some(Event::Done { .. })));
}

#[test]
fn a_progress_flood_is_told_at_a_bounded_rate_and_stopped_at_the_searchs_time() {
    let mut r = plain("flood-progress", &["flood-progress"]);
    let h = &mut r.host;
    let started = Instant::now();
    let op = h.request("flood-progress", search("", 5));
    let events = until_end(h, op, LONG);
    let took = started.elapsed();
    let told = events
        .iter()
        .filter(|e| matches!(e, Event::Progress { .. }))
        .count();
    assert_eq!(failure(&events), &Failure::Host(HostFailure::TimedOut));
    // At most one every 100 ms (the search's 2 s: about 20).
    assert!(told as u128 <= took.as_millis() / 100 + 2, "{told} in {took:?}");
    assert!(took < Duration::from_secs(6), "{took:?}");
}

#[test]
fn a_flood_of_results_past_its_page_is_stopped() {
    let mut r = plain("flood-results", &["flood-results"]);
    let h = &mut r.host;
    let op = h.request("flood-results", search("", 5));
    let events = until_end(h, op, LONG);
    let shown: usize = events
        .iter()
        .map(|e| match e {
            Event::Results { items, .. } => items.len(),
            _ => 0,
        })
        .sum();
    assert_eq!(shown, 0, "a first message past the page is refused whole");
    assert!(matches!(
        failure(&events),
        Failure::Host(HostFailure::Misbehaved(_))
    ));
}

#[test]
fn garbage_on_the_pipe_is_refused_without_reading_it_whole() {
    for name in ["oversized", "malformed", "garbage", "unknown-op"] {
        let (f, why, _, took) = misbehave(name, search("", 5));
        assert!(
            matches!(f, Failure::Host(HostFailure::Misbehaved(_))),
            "{name}: {f:?}"
        );
        assert!(matches!(why, Stop::Misbehaved(_)), "{name}: {why:?}");
        assert!(took < Duration::from_secs(5), "{name}: {took:?}");
    }
    let (f, why, _, _) = misbehave("truncated", search("", 5));
    assert_eq!(f, Failure::Host(HostFailure::Crashed));
    assert!(matches!(why, Stop::Crashed(_)));
}

#[test]
fn a_plugin_of_another_protocol_or_another_id_is_off_for_the_run_without_a_strike() {
    for (name, want) in [
        ("newer", "incompatible"),
        ("wrong-id", "invalid"),
    ] {
        let mut r = plain(name, &[name]);
        let h = &mut r.host;
        let op = h.request(name, search("", 5));
        let f = failure(&until_end(h, op, LONG)).clone();
        let (_, why, off, _) = until_stopped(h, LONG);
        match want {
            "incompatible" => {
                assert_eq!(why, Stop::Incompatible { plugin_newer: true });
                assert_eq!(f, Failure::Host(HostFailure::Incompatible { plugin_newer: true }));
            }
            _ => assert!(matches!(why, Stop::InvalidHello(_)), "{why:?}"),
        }
        assert!(off);
        assert_eq!(h.strikes(name), 0);
        let op = h.request(name, search("", 5));
        assert_eq!(
            failure(&until_end(h, op, LONG)),
            &Failure::Host(HostFailure::OffForTheRun)
        );
    }
}

#[test]
fn lies_and_hostile_paths_stop_the_plugin_and_hostile_content_is_unreadable() {
    for name in ["lie-size", "hostile-path"] {
        let (f, why, _, _) = misbehave(name, fetch("x", None));
        assert!(matches!(f, Failure::Host(HostFailure::Misbehaved(_))), "{name}: {f:?}");
        assert!(matches!(why, Stop::Misbehaved(_)), "{name}");
    }
    let mut r = plain("hostile-content", &["hostile-content"]);
    let store = r.host.store().clone();
    let h = &mut r.host;
    let op = h.request("hostile-content", fetch("x", None));
    let f = failure(&until_end(h, op, LONG)).clone();
    assert!(matches!(f, Failure::Host(HostFailure::Unreadable(ref why)) if !why.is_empty()), "{f:?}");
    assert_eq!(store.lock().unwrap().usage().memory, 0, "nothing kept");
    // Song data that does not read is no fault of the plugin's process.
    assert_eq!(h.strikes("hostile-content"), 0);
}

#[test]
fn past_the_cache_folders_cap_a_fetch_fails_and_the_plugin_is_told_to_stop_it() {
    let limits = StoreLimits {
        item_memory: 1 << 20,
        memory: 4 << 20,
        disk: 8 << 20,
    };
    let mut r = rig(
        "huge",
        &["huge-fetch"],
        &["huge-fetch"],
        limits,
        timeouts(),
    );
    let store = r.host.store().clone();
    let h = &mut r.host;
    let op = h.request("huge-fetch", fetch("x", None));
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::TooLarge)
    );
    // The plugin answers the cancel; it is not stopped.
    assert!(h.wait_event(Duration::from_millis(1500)).is_none());
    assert_eq!(h.strikes("huge-fetch"), 0);
    let usage = store.lock().unwrap().usage();
    assert_eq!((usage.memory, usage.disk), (0, 0));
}

#[test]
fn a_crash_in_the_middle_of_a_fetch_keeps_nothing() {
    let mut r = plain("crash-mid-fetch", &["crash-mid-fetch"]);
    let store = r.host.store().clone();
    let h = &mut r.host;
    let op = h.request("crash-mid-fetch", fetch("x", None));
    assert_eq!(
        failure(&until_end(h, op, LONG)),
        &Failure::Host(HostFailure::Crashed)
    );
    until_stopped(h, LONG);
    let usage = store.lock().unwrap().usage();
    assert_eq!((usage.items, usage.memory, usage.disk), (0, 0, 0));
}

#[test]
fn an_idle_plugin_is_shut_down_and_one_that_will_not_exit_is_killed() {
    let mut t = timeouts();
    t.idle = Duration::from_millis(300);
    for name in ["example", "slow-exit"] {
        let mut r = rig(name, &["slow-exit"], &[name], StoreLimits::default(), t);
        let h = &mut r.host;
        let op = h.request(name, search("", 5));
        until_end(h, op, LONG);
        let started = Instant::now();
        let (_, why, off, _) = until_stopped(h, LONG);
        assert_eq!(why, Stop::Idle, "{name}");
        assert!(!off);
        assert_eq!(h.strikes(name), 0);
        assert!(started.elapsed() < Duration::from_secs(4), "{name}");
        // Asked again, it starts again.
        let op = h.request(name, search("", 5));
        assert!(matches!(until_end(h, op, LONG).last(), Some(Event::Done { .. })));
    }
}

#[test]
fn a_plugin_that_exits_by_itself_with_nothing_running_is_no_strike() {
    let mut r = plain("exit-quietly", &["exit-quietly"]);
    let h = &mut r.host;
    assert!(h.start("exit-quietly"));
    let (events, why, off, _) = until_stopped(h, LONG);
    assert!(matches!(events.first(), Some(Event::Ready { .. })));
    assert_eq!(why, Stop::Exited);
    assert!(!off);
    assert_eq!(h.strikes("exit-quietly"), 0);
}

#[cfg(unix)]
#[test]
fn a_plugin_whose_child_holds_its_pipes_is_found_gone() {
    let (f, why, _, took) = misbehave("orphan", search("", 5));
    assert_eq!(f, Failure::Host(HostFailure::Crashed));
    assert!(matches!(why, Stop::Crashed(_)), "{why:?}");
    assert!(took < Duration::from_secs(4), "{took:?}");
}

#[test]
fn a_fifth_operation_at_once_is_busy_and_shutting_down_is_bounded() {
    let mut r = plain("busy", &["hang-search"]);
    let h = &mut r.host;
    let ops: Vec<OpId> = (0..5).map(|_| h.request("hang-search", search("", 5))).collect();
    let mut busy = 0;
    let deadline = Instant::now() + Duration::from_millis(500);
    while Instant::now() < deadline {
        if let Some(Event::Failed {
            op,
            failure: Failure::Host(HostFailure::Busy),
            ..
        }) = h.wait_event(Duration::from_millis(50))
        {
            assert_eq!(op, ops[4]);
            busy += 1;
        }
    }
    assert_eq!(busy, 1);
    let started = Instant::now();
    h.shutdown();
    assert!(started.elapsed() < Duration::from_secs(3), "{:?}", started.elapsed());
}

#[test]
fn a_plugin_stopped_as_it_starts_is_no_strike() {
    let mut r = plain("stop-early", &[]);
    let h = &mut r.host;
    assert!(h.start("example"));
    h.stop("example");
    let (_, why, off, _) = until_stopped(h, LONG);
    assert_eq!(why, Stop::Asked);
    assert!(!off);
    assert_eq!(h.strikes("example"), 0);
    // And it starts again when asked.
    let op = h.request("example", search("", 5));
    assert!(matches!(until_end(h, op, LONG).last(), Some(Event::Done { .. })));
}
